import { t } from "./i18n.js";
import { execFile } from "node:child_process";
import path from "node:path";
import { tmpdir } from "node:os";
import { rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { speaksLanguage, speech } from "./voice.js";

// 8-bit chiptune effects generated by scripts/make-sounds.js (see `npm run sounds`)
const SOUND_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "assets", "sounds");
const LADDER_STEPS = 6; // correct-0 … correct-5: the pitch climbs with your combo

// Voices macOS has for a language (`say -v ?`), the novelty ones left out, the best first: a premium or
// enhanced voice, then a plain named one. Read once, when the first word is spoken.
const NOVELTY = new Set(["Albert", "Bad News", "Bahh", "Bells", "Boing", "Bubbles", "Cellos", "Good News", "Jester", "Organ", "Superstar", "Trinoids", "Whisper", "Wobble", "Zarvox", "Fred", "Junior", "Kathy", "Ralph", "Grandma", "Grandpa", "Rocko"]);
const MAX_SPOKEN = 200; // characters: a long definition isn't read out whole
const SPEECH_CODE = { no: "nb", nn: "nb" }; // macOS reads Norwegian as Bokmål
const SPEAK_AFTER_MS = 500; // after the answer's chime, not over it
const VOICE_WAIT_MS = 8_000; // a natural voice that takes longer gives the word to the system's
const LATE_MS = 2_000; // a word that would come this much after its moment isn't read at all
let voices = null;
function voicesOnce() {
  voices ??= new Promise((resolve) =>
    execFile("say", ["-v", "?"], (err, out) =>
      resolve(err ? [] : String(out).split("\n").map((line) => line.match(/^(.+?)\s+([a-z]{2,3})_([A-Za-z0-9]+)\s+#/)).filter(Boolean).map(([, name, lang, region]) => ({ name: name.trim(), lang, region })))
    )
  );
  return voices;
}
// the region most learners mean (English from the US or Britain, not India; Chinese from the mainland)
const REGIONS = { en: ["US", "GB"], zh: ["CN", "TW"], pt: ["PT", "BR"], es: ["ES", "MX"], fr: ["FR"], de: ["DE"], nl: ["NL"] };
const rank = (voice) => {
  const regions = REGIONS[voice.lang] ?? [];
  const region = regions.includes(voice.region) ? regions.indexOf(voice.region) : regions.length;
  const quality = /\((Premium|Enhanced)\)/.test(voice.name) ? 0 : /\(/.test(voice.name) ? 2 : 1;
  return region * 10 + quality;
};
export async function voiceFor(lang) {
  const code = SPEECH_CODE[lang] ?? lang;
  const found = (await voicesOnce()).filter((voice) => voice.lang === code && !NOVELTY.has(voice.name));
  return found.sort((a, b) => rank(a) - rank(b))[0]?.name ?? null;
}

// a voice that can't work until something is changed in /settings: not asked again this run
const VOICE_STOPS = new Set(["noKey", "badKey", "noCredit", "noVoice"]);

export function createAlerts(initial = {}) {
  const enabled = process.platform === "darwin";
  // voice: settings.voice (null: the system's voices); onVoiceProblem(message): told once when it stops
  const config = { sound: true, volume: 0.5, speak: false, voice: null, onVoiceProblem: null, ...initial };
  // one word at a time: a newer one (or switching pronunciation off) cancels the one waiting or playing
  let turn = 0;
  let waiting = null;
  let speaking = null;
  let fetching = null;
  let voiceDown = false;
  const hush = () => {
    turn += 1;
    clearTimeout(waiting);
    speaking?.kill();
    fetching?.abort();
    waiting = speaking = fetching = null;
  };

  const play = (name) => {
    if (!config.sound || !enabled) return;
    execFile("afplay", ["-v", String(config.volume), path.join(SOUND_DIR, `${name}.wav`)], () => {});
  };
  const playVoice = (file, done = () => {}) => {
    const voiceOut = (speaking = execFile("afplay", ["-v", String(config.volume), file], done));
    voiceOut.unref();
  };

  // the word in the system's voice: rendered to a file and played with afplay, so it follows the volume
  // like the sounds do (say's own volume command is ignored by today's voices)
  async function sayIt(words, lang, mine, at) {
    const voice = await voiceFor(lang);
    if (!voice || mine !== turn) return;
    const file = path.join(tmpdir(), `dracosh-${process.pid}-${Date.now()}.aiff`);
    waiting = setTimeout(() => {
      waiting = null;
      if (!config.speak || mine !== turn) return;
      const render = (speaking = execFile("say", ["-v", voice, "-o", file, "--", words], (err) => {
        if (err || speaking !== render) return void rm(file, { force: true }).catch(() => {});
        playVoice(file, () => rm(file, { force: true }).catch(() => {}));
      }));
      render.unref();
    }, Math.max(0, at - Date.now()));
    waiting.unref(); // quitting right after an answer doesn't wait for the word
  }

  return {
    play,
    configure(patch) {
      // a voice picked again in /settings (a new key, say) is a new object: tried again
      if ("voice" in patch && patch.voice !== config.voice) voiceDown = false;
      Object.assign(config, patch);
      if (!config.speak) hush();
    },
    // an audio file played now at the set volume, whatever the settings (a voice heard while picking it)
    playFile(file) {
      if (!enabled) return;
      hush();
      playVoice(file);
    },
    // a new question while you're in another window: sound plus a Notification Center banner
    ask() {
      play("ask");
      // the text goes to AppleScript as an argument, never into the script itself
      if (enabled) execFile("osascript", ["-e", "on run argv", "-e", 'display notification (item 1 of argv) with title "Dracosh"', "-e", "end run", t("alerts.newCard")], () => {});
    },
    // a word read aloud in its language (/settings → Pronunciation), after the answer's chime, not over
    // it: in the natural voice when one is set and speaks the language, else in the system's (nothing
    // when macOS has no voice for it). A natural voice that fails leaves the word to the system's.
    async speak(text, lang) {
      hush();
      if (!config.speak || !enabled || !text || !lang) return;
      const mine = turn;
      const at = Date.now() + SPEAK_AFTER_MS;
      const words = text.replace(/\[\[|\]\]|[{}\\]/g, "").slice(0, MAX_SPOKEN); // [[…]] would be a command; cloze braces aren't words
      if (!words.trim()) return;
      // a voice that stopped working still plays the words it made before (no request: no key needed)
      if (config.voice && speaksLanguage(lang)) {
        const controller = (fetching = new AbortController());
        try {
          const file = await speech(config.voice, words.trim(), lang, { signal: controller.signal, timeoutMs: VOICE_WAIT_MS, ...(voiceDown ? { key: null } : {}) });
          if (mine !== turn) return;
          fetching = null;
          waiting = setTimeout(() => {
            waiting = null;
            if (config.speak && mine === turn) playVoice(file);
          }, Math.max(0, at - Date.now()));
          waiting.unref();
          return;
        } catch (err) {
          if (controller.signal.aborted || mine !== turn) return;
          fetching = null;
          if (VOICE_STOPS.has(err.code) && !voiceDown) {
            voiceDown = true;
            config.onVoiceProblem?.(err.message);
          }
          if (Date.now() > at + LATE_MS) return; // the moment has passed: better quiet than late
        }
      }
      await sayIt(words, lang, mine, at);
    },
    // The biggest thing that just happened wins: evolution > goal > combo cheer > the answer itself.
    // On a plain correct answer the pitch rises with the combo and resets on a miss. Badges ring
    // on their own, each as its line lights up (see BadgeUnlock).
    result(result, { cheers = [], combo = 0 } = {}) {
      if (result === "wrong") return play("wrong");
      for (const kind of ["evolve", "goal", "combo"]) {
        if (cheers.includes(kind)) return play(kind);
      }
      if (result === "typo" || result === "article" || result === "umlaut" || result === "article-umlaut") return play("close");
      play(`correct-${Math.min(Math.max(combo - 1, 0), LADDER_STEPS - 1)}`);
    }
  };
}
